// Package nicedroid carries the repository-level embedded model catalog.
//
// manifest.json is generated by tools/extract-manifest from a Droid CLI binary
// and refreshed by .github/workflows/update-models.yml whenever Factory ships a
// new CLI. Nothing else in the module reads the file directly: internal/config
// decodes this copy at startup and builds the model catalog from it.
package nicedroid

import _ "embed"

//go:embed manifest.json
var ManifestJSON []byte
